struct Paths {
    config_file_path: Option<PathBuf>, // if custom dir is file, this is that file
    config_dir: Option<PathBuf>, // if custom dir is dir, this is that dir
    is_file_config: bool,
}

fn resolve_config_path(custom: Option<&String>) -> Result<Paths, String> {
    if let Some(p_str) = custom {
        let p = PathBuf::from(p_str);
        if p.is_file() {
            // backward compat: file path
            if let Some(parent) = p.parent() {
                // if parent exists, config_dir is parent? But for themes handling we need to know it's file
                // For config reading, we read file directly
                Ok(Paths {
                    config_file_path: Some(p.clone()),
                    config_dir: parent.to_path_buf().into(),
                    is_file_config: true,
                })
            } else {
                Ok(Paths {
                    config_file_path: Some(p.clone()),
                    config_dir: None,
                    is_file_config: true,
                })
            }
        } else if p.is_dir() {
            Ok(Paths {
                config_file_path: Some(p.join("config.toml")),
                config_dir: Some(p),
                is_file_config: false,
            })
        } else {
            // path doesn't exist
            Err(format!("Provided custom directory doesn't exit. Path: {}", p_str))
        }
    } else {
        // default
        let home = dirs::home_dir().unwrap_or_else(|| PathBuf::from("/home/agent"));
        let default_dir = home.join(".config/tui-journal");
        Ok(Paths {
            config_file_path: Some(default_dir.join("config.toml")),
            config_dir: Some(default_dir),
            is_file_config: false,
        })
    }
}

fn load_config(paths: &Paths) -> Result<Config, String> {
    let mut cfg = Config::default();
    // try to read file if exists
    if let Some(file_path) = &paths.config_file_path {
        if file_path.is_file() {
            let content = fs::read_to_string(file_path).map_err(|e| format!("Failed to read configuration file. Error infos: {}", e))?;
            // try to parse TOML
            // We need to capture TOML parse errors with detailed message as original
            match toml::from_str::<RawConfig>(&content) {
                Ok(raw) => {
                    // Apply raw to cfg
                    if let Some(bt) = raw.backend_type {
                        cfg.backend_type = bt;
                    }
                    if let Some(v) = raw.scroll_per_page { cfg.scroll_per_page = v; }
                    if let Some(v) = raw.sync_os_clipboard { cfg.sync_os_clipboard = v; }
                    if let Some(v) = raw.history_limit { cfg.history_limit = v; }
                    if let Some(v) = raw.colored_tags { cfg.colored_tags = v; }
                    if let Some(v) = raw.datum_visibility { cfg.datum_visibility = v; }
                    if let Some(v) = raw.app_state_dir { cfg.app_state_dir = v; }
                    if let Some(exp) = raw.export {
                        if let Some(v) = exp.show_confirmation { cfg.export.show_confirmation = v; }
                        if let Some(v) = exp.default_path { cfg.export.default_path = Some(v); }
                        else if let Some(v) = exp.path { 
                            // path alias: treat as default_path for reading
                            // but original seems to ignore path unless it's default_path? Actually earlier we tested path key and it didn't affect print-config,
                            // but we tested default_path and it did. So for backward compat we can treat path as default_path as well.
                            // However print-config didn't show path when only path set. So let's store path as default_path if default_path missing?
                            cfg.export.default_path = Some(v);
                        }
                    }
                    if let Some(ed) = raw.external_editor {
                        if let Some(v) = ed.command { cfg.external_editor.command = Some(v); }
                        if let Some(v) = ed.args { cfg.external_editor.args = v; }
                        if let Some(v) = ed.auto_save { cfg.external_editor.auto_save = v; }
                        if let Some(v) = ed.temp_file_extension { cfg.external_editor.temp_file_extension = v; }
                    }
                    if let Some(jb) = raw.json_backend {
                        if let Some(v) = jb.file_path { cfg.json_backend.file_path = v; }
                    }
                    if let Some(sb) = raw.sqlite_backend {
                        if let Some(v) = sb.file_path { cfg.sqlite_backend.file_path = v; }
                    }
                    Ok(cfg)
                }
                Err(e) => {
                    // TOML parse error formatting similar to original:
                    // Original message: "Error: Failed to read configuration file. Error infos: TOML parse error at line X, column Y ..."
                    // The toml crate's error Display should already contain that line
                    // So we can produce "Failed to read configuration file. Error infos: {}"
                    Err(format!("Failed to read configuration file. Error infos: {}", e))
                }
            }
        } else {
            // file doesn't exist, use default
            Ok(cfg)
        }
    } else {
        Ok(cfg)
    }
}

