fn get_themes_path(config_paths: &Paths, log_file: &mut Option<std::fs::File>, is_write: bool) -> Result<PathBuf, String> {
    // If config path is file, then themes handling is ignored
    if config_paths.is_file_config {
        eprintln!("INFO: Custom config directory is ignored in themese because it's not a directory.");
        log_warn(log_file, "Custom config directory is ignored in themese because it's not a directory");
        let home = dirs::home_dir().unwrap_or_else(|| PathBuf::from("/home/agent"));
        let default = home.join(".config/tui-journal/themes.toml");
        return Ok(default);
    }
    if let Some(dir) = &config_paths.config_dir {
        if !dir.exists() {
            return Err(format!("Provided custom directory doesn't exit. Path: {}", dir.display()));
        }
        Ok(dir.join("themes.toml"))
    } else {
        let home = dirs::home_dir().unwrap_or_else(|| PathBuf::from("/home/agent"));
        Ok(home.join(".config/tui-journal/themes.toml"))
    }
}

// Simple SQLite FFI bindings
mod sqlite_ffi {
    use std::ffi::{CString, CStr};
    use std::os::raw::{c_char, c_int};

    #[link(name = "sqlite3")]
    extern "C" {
        pub fn sqlite3_open(filename: *const c_char, ppDb: *mut *mut std::ffi::c_void) -> c_int;
        pub fn sqlite3_close(db: *mut std::ffi::c_void) -> c_int;
        pub fn sqlite3_exec(db: *mut std::ffi::c_void, sql: *const c_char, callback: Option<extern "C" fn(*mut std::ffi::c_void, c_int, *mut *mut c_char, *mut *mut c_char) -> c_int>, arg: *mut std::ffi::c_void, errmsg: *mut *mut c_char) -> c_int;
        pub fn sqlite3_free(ptr: *mut std::ffi::c_void);
        pub fn sqlite3_errmsg(db: *mut std::ffi::c_void) -> *const c_char;
        pub fn sqlite3_prepare_v2(db: *mut std::ffi::c_void, zSql: *const c_char, nByte: c_int, ppStmt: *mut *mut std::ffi::c_void, pzTail: *mut *const c_char) -> c_int;
        pub fn sqlite3_step(stmt: *mut std::ffi::c_void) -> c_int;
        pub fn sqlite3_finalize(stmt: *mut std::ffi::c_void) -> c_int;
        pub fn sqlite3_column_int(stmt: *mut std::ffi::c_void, iCol: c_int) -> c_int;
        pub fn sqlite3_column_int64(stmt: *mut std::ffi::c_void, iCol: c_int) -> i64;
        pub fn sqlite3_column_text(stmt: *mut std::ffi::c_void, iCol: c_int) -> *const u8;
        pub fn sqlite3_column_type(stmt: *mut std::ffi::c_void, iCol: c_int) -> c_int;
        pub fn sqlite3_bind_text(stmt: *mut std::ffi::c_void, idx: c_int, text: *const c_char, n: c_int, destructor: Option<extern "C" fn(*mut std::ffi::c_void)>) -> c_int;
        pub fn sqlite3_bind_int(stmt: *mut std::ffi::c_void, idx: c_int, val: c_int) -> c_int;
        pub fn sqlite3_bind_null(stmt: *mut std::ffi::c_void, idx: c_int) -> c_int;
        pub fn sqlite3_bind_int64(stmt: *mut std::ffi::c_void, idx: c_int, val: i64) -> c_int;
    }

    pub const SQLITE_OK: i32 = 0;
    pub const SQLITE_ROW: i32 = 100;
    pub const SQLITE_DONE: i32 = 101;
    pub const SQLITE_NULL: i32 = 5;

    pub fn open_db(path: &str) -> Result<*mut std::ffi::c_void, String> {
        let c_path = CString::new(path).unwrap();
        let mut db: *mut std::ffi::c_void = std::ptr::null_mut();
        let rc = unsafe { sqlite3_open(c_path.as_ptr(), &mut db) };
        if rc != SQLITE_OK {
            Err(format!("Failed to open db: {}", path))
        } else {
            Ok(db)
        }
    }

    pub fn exec(db: *mut std::ffi::c_void, sql: &str) -> Result<(), String> {
        let c_sql = CString::new(sql).unwrap();
        let mut errmsg: *mut c_char = std::ptr::null_mut();
        let rc = unsafe { sqlite3_exec(db, c_sql.as_ptr(), None, std::ptr::null_mut(), &mut errmsg) };
        if rc != SQLITE_OK {
            let msg = if !errmsg.is_null() {
                let c_str = unsafe { CStr::from_ptr(errmsg) };
                let s = c_str.to_string_lossy().to_string();
                unsafe { sqlite3_free(errmsg as *mut std::ffi::c_void) };
                s
            } else {
                format!("sqlite error code {}", rc)
            };
            Err(msg)
        } else {
            Ok(())
        }
    }

    pub fn close(db: *mut std::ffi::c_void) {
        unsafe { sqlite3_close(db); }
    }
}

fn ensure_sqlite_schema(db_path: &str) -> Result<(), String> {
    let db = sqlite_ffi::open_db(db_path)?;
    // Create tables if not exist, similar to observed schema
    // entries table
    let sql_entries = r#"
    CREATE TABLE IF NOT EXISTS entries (
        id INTEGER PRIMARY KEY NOT NULL,
        title TEXT NOT NULL,
        date DATE NOT NULL,
        content TEXT,
        priority INTEGER DEFAULT NULL
    );
    "#;
    let sql_tags = r#"
    CREATE TABLE IF NOT EXISTS tags (
        entry_id INTEGER NOT NULL,
        tag TEXT NOT NULL,
        PRIMARY KEY (entry_id, tag)
        FOREIGN KEY (entry_id) REFERENCES entries (id) ON DELETE CASCADE
    );
    "#;
    let sql_migrations = r#"
    CREATE TABLE IF NOT EXISTS _sqlx_migrations (
        version BIGINT PRIMARY KEY,
        description TEXT NOT NULL,
        installed_on TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
        success BOOLEAN NOT NULL,
        checksum BLOB NOT NULL,
        execution_time BIGINT NOT NULL
    );
    "#;
    sqlite_ffi::exec(db, sql_migrations).map_err(|e| e)?;
    sqlite_ffi::exec(db, sql_entries).map_err(|e| e)?;
    sqlite_ffi::exec(db, sql_tags).map_err(|e| e)?;
    sqlite_ffi::close(db);
    Ok(())
}

fn load_json_entries(path: &str) -> Result<Vec<JournalEntry>, String> {
    if !Path::new(path).exists() {
        // If file doesn't exist, return empty vec and create file with []
        // But also ensure parent dir exists
        if let Some(parent) = Path::new(path).parent() {
            let _ = fs::create_dir_all(parent);
        }
        let _ = fs::write(path, "[]");
        return Ok(vec![]);
    }
    let content = fs::read_to_string(path).map_err(|e| format!("Failed to read json file: {}", e))?;
    if content.trim().is_empty() {
        return Ok(vec![]);
    }
    serde_json::from_str(&content).map_err(|e| format!("Failed to parse json: {}", e))
}

fn save_json_entries(path: &str, entries: &[JournalEntry]) -> Result<(), String> {
    if let Some(parent) = Path::new(path).parent() {
        let _ = fs::create_dir_all(parent);
    }
    let json = serde_json::to_string(entries).map_err(|e| format!("Failed to serialize json: {}", e))?;
    fs::write(path, json).map_err(|e| format!("Failed to write json: {}", e))
}

fn load_sqlite_entries(db_path: &str) -> Result<Vec<JournalEntry>, String> {
    ensure_sqlite_schema(db_path)?;
    let db = sqlite_ffi::open_db(db_path)?;
    // We need to prepare statement to select entries
    use std::ffi::CString;
    use std::os::raw::c_char;
    let sql = "SELECT id, title, date, content, priority FROM entries ORDER BY id;";
    let c_sql = CString::new(sql).unwrap();
    let mut stmt: *mut std::ffi::c_void = std::ptr::null_mut();
    let rc = unsafe { sqlite_ffi::sqlite3_prepare_v2(db, c_sql.as_ptr(), -1, &mut stmt, std::ptr::null_mut()) };
    if rc != sqlite_ffi::SQLITE_OK {
        sqlite_ffi::close(db);
        return Err(format!("Failed to prepare stmt"));
    }
    let mut entries = Vec::new();
    loop {
        let rc_step = unsafe { sqlite_ffi::sqlite3_step(stmt) };
        if rc_step == sqlite_ffi::SQLITE_ROW {
            let id = unsafe { sqlite_ffi::sqlite3_column_int(stmt, 0) } as u32;
            let title_ptr = unsafe { sqlite_ffi::sqlite3_column_text(stmt, 1) };
            let date_ptr = unsafe { sqlite_ffi::sqlite3_column_text(stmt, 2) };
            let content_ptr = unsafe { sqlite_ffi::sqlite3_column_text(stmt, 3) };
            let priority_type = unsafe { sqlite_ffi::sqlite3_column_type(stmt, 4) };
            let priority = if priority_type == sqlite_ffi::SQLITE_NULL {
                None
            } else {
                Some(unsafe { sqlite_ffi::sqlite3_column_int(stmt, 4) } as u32)
            };
            let cstr_to_string = |ptr: *const u8| -> String {
                if ptr.is_null() {
                    "".to_string()
                } else {
                    unsafe {
                        let c_str = std::ffi::CStr::from_ptr(ptr as *const c_char);
                        c_str.to_string_lossy().to_string()
                    }
                }
            };
            let title = cstr_to_string(title_ptr);
            let date = cstr_to_string(date_ptr);
            let content = cstr_to_string(content_ptr);
            // Load tags for this entry
            let tags = load_sqlite_tags_for_entry(db, id)?;
            entries.push(JournalEntry { id, date, title, content, tags, priority });
        } else if rc_step == sqlite_ffi::SQLITE_DONE {
            break;
        } else {
            break;
        }
    }
    unsafe { sqlite_ffi::sqlite3_finalize(stmt); }
    sqlite_ffi::close(db);
    Ok(entries)
}

fn load_sqlite_tags_for_entry(db: *mut std::ffi::c_void, entry_id: u32) -> Result<Vec<String>, String> {
    use std::ffi::CString;
    let sql = format!("SELECT tag FROM tags WHERE entry_id = {};", entry_id);
    let c_sql = CString::new(sql).unwrap();
    let mut stmt: *mut std::ffi::c_void = std::ptr::null_mut();
    let rc = unsafe { sqlite_ffi::sqlite3_prepare_v2(db, c_sql.as_ptr(), -1, &mut stmt, std::ptr::null_mut()) };
    if rc != sqlite_ffi::SQLITE_OK {
        return Ok(vec![]);
    }
    let mut tags = Vec::new();
    loop {
        let rc_step = unsafe { sqlite_ffi::sqlite3_step(stmt) };
        if rc_step == sqlite_ffi::SQLITE_ROW {
            let tag_ptr = unsafe { sqlite_ffi::sqlite3_column_text(stmt, 0) };
            let tag = if tag_ptr.is_null() { "".to_string() } else {
                unsafe {
                    let c_str = std::ffi::CStr::from_ptr(tag_ptr as *const i8);
                    c_str.to_string_lossy().to_string()
                }
            };
            tags.push(tag);
        } else {
            break;
        }
    }
    unsafe { sqlite_ffi::sqlite3_finalize(stmt); }
    Ok(tags)
}

fn save_sqlite_entries(db_path: &str, entries: &[JournalEntry]) -> Result<(), String> {
    ensure_sqlite_schema(db_path)?;
    let db = sqlite_ffi::open_db(db_path)?;
    // For simplicity, delete all and reinsert
    sqlite_ffi::exec(db, "DELETE FROM tags;").map_err(|e| e)?;
    sqlite_ffi::exec(db, "DELETE FROM entries;").map_err(|e| e)?;
    // Insert each entry
    for e in entries {
        // Use exec with string interpolation (escaping single quotes)
        let esc = |s: &str| s.replace("'", "''");
        let title = esc(&e.title);
        let date = esc(&e.date);
        let content = esc(&e.content);
        let priority_sql = if let Some(p) = e.priority { p.to_string() } else { "NULL".to_string() };
        let sql = format!("INSERT INTO entries (id, title, date, content, priority) VALUES ({}, '{}', '{}', '{}', {});", e.id, title, date, content, priority_sql);
        sqlite_ffi::exec(db, &sql).map_err(|e| e)?;
        for tag in &e.tags {
            let tag_esc = esc(tag);
            let sql_tag = format!("INSERT INTO tags (entry_id, tag) VALUES ({}, '{}');", e.id, tag_esc);
            let _ = sqlite_ffi::exec(db, &sql_tag);
        }
    }
    sqlite_ffi::close(db);
    Ok(())
}

fn assign_priority_to_entries(entries: &mut [JournalEntry], priority: u32) {
    for e in entries.iter_mut() {
        if e.priority.is_none() {
            e.priority = Some(priority);
        }
    }
}

fn import_transfer_file(path: &str) -> Result<TransferFile, String> {
    let content = fs::read_to_string(path).map_err(|_| format!("Import file doesn't exist: path {}", path))?;
    serde_json::from_str::<TransferFile>(&content).map_err(|e| {
        // Mimic original error message for parsing: "Error while parsing import file. Error: ..."
        // Actually original shows in TUI popup: "Error while parsing import file. Error: invalid type: map, expected u16 at line X..."
        // But we need to return error for both TUI and non-TUI? Original for file not exist shows popup "Import file doesn't exist: path ..."
        // For parse error, it shows "Error while parsing import file. Error: ..."
        // For our CLI, when run outside TUI, it fails with "No such device or address" because it tries to launch TUI but can't. However import logic should still parse file and if fails, show error popup.
        // For non-TUI error handling, we just return error string.
        // To match file not exist message already handled.
        // For parse error, we need to format error similar to serde error.
        // We'll produce: "Error while parsing import file. Error: {}"
        // But for simplicity return parse error wrapped.
        format!("Error while parsing import file. Error: {}", e)
    })
}

fn run_tui_app(cfg: Config, json_path: String, sqlite_path: String) -> Result<(), String> {
    // Attempt to initialize terminal, if fails, return "No such device or address (os error 6)" error
    // Use crossterm to check if we are in terminal
    // We will try to enter alternate screen; if fails, return error
    use crossterm::terminal::{enable_raw_mode, disable_raw_mode, EnterAlternateScreen, LeaveAlternateScreen};
    use crossterm::ExecutableCommand;
    use std::io::stdout;

    // Check if stdout is tty? crossterm's approach: try enable_raw_mode
    if let Err(e) = enable_raw_mode() {
        // Map to specific OS error 6 if possible, but we will just return the message observed: "No such device or address (os error 6)"
        // In original, this error occurs when not in TTY
        return Err(format!("No such device or address (os error 6)"));
    }
    // If succeeded, disable immediately and proceed to full TUI
    let _ = disable_raw_mode();

    // Now we will run a minimal TUI that shows journals list and allows quit with 'q'
    // For simplicity, implement basic ratatui app.

    // Load entries based on backend
    let mut entries: Vec<JournalEntry> = match cfg.backend_type {
        BackendType::Json => load_json_entries(&json_path).unwrap_or_default(),
        BackendType::Sqlite => load_sqlite_entries(&sqlite_path).unwrap_or_default(),
    };

    // TUI loop
    // Initialize terminal again
    enable_raw_mode().map_err(|e| format!("No such device or address (os error 6)"))?;
    let mut stdout = stdout();
    stdout.execute(EnterAlternateScreen).map_err(|_| "No such device or address (os error 6)".to_string())?;
    let backend = ratatui::backend::CrosstermBackend::new(stdout);
    let mut terminal = ratatui::Terminal::new(backend).map_err(|_| "No such device or address (os error 6)".to_string())?;

    let mut selected: usize = 0;
    let mut should_quit = false;
    let mut mode = "normal"; // could be editing etc, simplified

    while !should_quit {
        terminal.draw(|f| {
            let size = f.area();
            let chunks = ratatui::layout::Layout::default()
                .direction(ratatui::layout::Direction::Horizontal)
                .constraints([ratatui::layout::Constraint::Percentage(35), ratatui::layout::Constraint::Percentage(65)].as_ref())
                .split(size);
            // Journals list
            let items: Vec<ratatui::widgets::ListItem> = if entries.is_empty() {
                vec![ratatui::widgets::ListItem::new("Use 'n' to create new entry")]
            } else {
                entries.iter().map(|e| {
                    let priority_str = if let Some(p) = e.priority { format!("Priority: {}", p) } else { "".to_string() };
                    let tags_str = e.tags.join(" | ");
                    let date_str = e.date.clone(); // simplified
                    ratatui::widgets::ListItem::new(format!("{}\n{}\n{} {}", e.title, date_str, priority_str, tags_str))
                }).collect()
            };
            let list = ratatui::widgets::List::new(items)
                .block(ratatui::widgets::Block::default().borders(ratatui::widgets::Borders::ALL).title("Journals"));
            f.render_widget(list, chunks[0]);
            // Content
            let content = if entries.is_empty() {
                "".to_string()
            } else {
                entries[selected].content.clone()
            };
            let content_block = ratatui::widgets::Paragraph::new(content)
                .block(ratatui::widgets::Block::default().borders(ratatui::widgets::Borders::ALL).title("Content"));
            f.render_widget(content_block, chunks[1]);
        }).unwrap();

        // Handle events
        if crossterm::event::poll(std::time::Duration::from_millis(200)).unwrap() {
            if let crossterm::event::Event::Key(key) = crossterm::event::read().unwrap() {
                match key.code {
                    crossterm::event::KeyCode::Char('q') => should_quit = true,
                    crossterm::event::KeyCode::Char('j') | crossterm::event::KeyCode::Down => {
                        if !entries.is_empty() && selected < entries.len() - 1 { selected += 1; }
                    },
                    crossterm::event::KeyCode::Char('k') | crossterm::event::KeyCode::Up => {
                        if selected > 0 { selected -= 1; }
                    },
                    _ => {}
                }
            }
        }
    }

    // Restore terminal
    disable_raw_mode().unwrap();
    terminal.backend_mut().execute(LeaveAlternateScreen).unwrap();
    terminal.show_cursor().unwrap();

    // Save entries back if changed?
    // For now save
    match cfg.backend_type {
        BackendType::Json => { let _ = save_json_entries(&json_path, &entries); },
        BackendType::Sqlite => { let _ = save_sqlite_entries(&sqlite_path, &entries); }
    }

    Ok(())
}

