                            match get_themes_path(&config_paths, &mut log_file_handle, true) {
                                Ok(p) => {
                                    if p.exists() {
                                        eprintln!("Error: Themes file already exists. Path: {}", p.display());
                                        std::process::exit(1);
                                    }
                                    if let Some(parent) = p.parent() {
                                        if let Err(e) = fs::create_dir_all(parent) {
                                            eprintln!("Error: Error while writing default themes to file\n\nCaused by:\n    {}", e);
