                                        }
                                    }
                                },
                                Err(e) => {
                                    eprintln!("Error: {}", e);
                                    std::process::exit(1);
                                }
                            }
                            return;
                        },
                        _ => {}
                    }
                }
                // If no subcommand, show help for theme
                // clap should handle help, but we can print
                println!("Provides commands regarding changing themes and styles of the app");
                return;
            },
            _ => {}
        }
    }

    // No subcommand: run main TUI app
    let json_path = config.json_backend.file_path.clone();
    let sqlite_path = config.sqlite_backend.file_path.clone();
    match run_tui_app(config, json_path, sqlite_path) {
        Ok(_) => {},
        Err(e) => {
            eprintln!("Error: {}", e);
            std::process::exit(1);
