fn resolve_config_path(custom: Option<&String>) -> Result<Paths, String> {
    if let Some(p_str) = custom {
        let p = PathBuf::from(p_str);
        if p.is_file() {
            // backward compat: file path
            if let Some(parent) = p.parent() {
                // if parent exists, config_dir is parent? But for themes handling we need to know it's file
                // For config reading, we read file directly
                Ok(Paths {
                    config_file_path: Some(p.clone()),
                    config_dir: parent.to_path_buf().into(),
                    is_file_config: true,
                })
            } else {
                Ok(Paths {
                    config_file_path: Some(p.clone()),
                    config_dir: None,
                    is_file_config: true,
                })
            }
        } else if p.is_dir() {
            Ok(Paths {
                config_file_path: Some(p.join("config.toml")),
                config_dir: Some(p),
                is_file_config: false,
            })
        } else {
            // path doesn't exist
            Err(format!("Provided custom directory doesn't exit. Path: {}", p_str))
        }
    } else {
        // default
        let home = dirs::home_dir().unwrap_or_else(|| PathBuf::from("/home/agent"));
        let default_dir = home.join(".config/tui-journal");
        Ok(Paths {
            config_file_path: Some(default_dir.join("config.toml")),
            config_dir: Some(default_dir),
            is_file_config: false,
        })
    }
}

