mod sqlite_ffi {
    use std::ffi::{CString, CStr};
    use std::os::raw::{c_char, c_int};

    #[link(name = "sqlite3")]
    extern "C" {
        pub fn sqlite3_open(filename: *const c_char, ppDb: *mut *mut std::ffi::c_void) -> c_int;
        pub fn sqlite3_close(db: *mut std::ffi::c_void) -> c_int;
        pub fn sqlite3_exec(db: *mut std::ffi::c_void, sql: *const c_char, callback: Option<extern "C" fn(*mut std::ffi::c_void, c_int, *mut *mut c_char, *mut *mut c_char) -> c_int>, arg: *mut std::ffi::c_void, errmsg: *mut *mut c_char) -> c_int;
        pub fn sqlite3_free(ptr: *mut std::ffi::c_void);
        pub fn sqlite3_prepare_v2(db: *mut std::ffi::c_void, zSql: *const c_char, nByte: c_int, ppStmt: *mut *mut std::ffi::c_void, pzTail: *mut *const c_char) -> c_int;
        pub fn sqlite3_step(stmt: *mut std::ffi::c_void) -> c_int;
        pub fn sqlite3_finalize(stmt: *mut std::ffi::c_void) -> c_int;
        pub fn sqlite3_column_int(stmt: *mut std::ffi::c_void, iCol: c_int) -> c_int;
        pub fn sqlite3_column_text(stmt: *mut std::ffi::c_void, iCol: c_int) -> *const u8;
        pub fn sqlite3_column_type(stmt: *mut std::ffi::c_void, iCol: c_int) -> c_int;
    }

    pub const SQLITE_OK: i32 = 0;
    pub const SQLITE_ROW: i32 = 100;
    pub const SQLITE_DONE: i32 = 101;
    pub const SQLITE_NULL: i32 = 5;

    pub fn open_db(path: &str) -> Result<*mut std::ffi::c_void, String> {
        let c_path = CString::new(path).unwrap();
        let mut db: *mut std::ffi::c_void = std::ptr::null_mut();
        let rc = unsafe { sqlite3_open(c_path.as_ptr(), &mut db) };
        if rc != SQLITE_OK {
            Err(format!("Failed to open db: {}", path))
        } else {
            Ok(db)
        }
    }

    pub fn exec(db: *mut std::ffi::c_void, sql: &str) -> Result<(), String> {
        let c_sql = CString::new(sql).unwrap();
        let mut errmsg: *mut c_char = std::ptr::null_mut();
        let rc = unsafe { sqlite3_exec(db, c_sql.as_ptr(), None, std::ptr::null_mut(), &mut errmsg) };
        if rc != SQLITE_OK {
            let msg = if !errmsg.is_null() {
                let c_str = unsafe { CStr::from_ptr(errmsg) };
                let s = c_str.to_string_lossy().to_string();
                unsafe { sqlite3_free(errmsg as *mut std::ffi::c_void) };
                s
            } else {
                format!("sqlite error code {}", rc)
            };
            Err(msg)
        } else {
            Ok(())
        }
    }

    pub fn close(db: *mut std::ffi::c_void) {
        unsafe { sqlite3_close(db); }
    }
}

fn ensure_sqlite_schema(db_path: &str) -> Result<(), String> {
    let db = sqlite_ffi::open_db(db_path)?;
    let sql_entries = r#"
    CREATE TABLE IF NOT EXISTS entries (
        id INTEGER PRIMARY KEY NOT NULL,
        title TEXT NOT NULL,
        date DATE NOT NULL,
        content TEXT,
        priority INTEGER DEFAULT NULL
    );
    "#;
    let sql_tags = r#"
    CREATE TABLE IF NOT EXISTS tags (
        entry_id INTEGER NOT NULL,
        tag TEXT NOT NULL,
        PRIMARY KEY (entry_id, tag)
        FOREIGN KEY (entry_id) REFERENCES entries (id) ON DELETE CASCADE
    );
    "#;
    let sql_migrations = r#"
    CREATE TABLE IF NOT EXISTS _sqlx_migrations (
        version BIGINT PRIMARY KEY,
        description TEXT NOT NULL,
        installed_on TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
        success BOOLEAN NOT NULL,
        checksum BLOB NOT NULL,
        execution_time BIGINT NOT NULL
    );
    "#;
    sqlite_ffi::exec(db, sql_migrations).map_err(|e| e)?;
    sqlite_ffi::exec(db, sql_entries).map_err(|e| e)?;
    sqlite_ffi::exec(db, sql_tags).map_err(|e| e)?;
    sqlite_ffi::close(db);
    Ok(())
}

fn load_json_entries(path: &str) -> Result<Vec<JournalEntry>, String> {
    if !Path::new(path).exists() {
        if let Some(parent) = Path::new(path).parent() {
            let _ = fs::create_dir_all(parent);
        }
        let _ = fs::write(path, "[]");
        return Ok(vec![]);
    }
    let content = fs::read_to_string(path).map_err(|e| format!("Failed to read json file: {}", e))?;
    if content.trim().is_empty() {
        return Ok(vec![]);
    }
    serde_json::from_str(&content).map_err(|e| format!("Failed to parse json: {}", e))
}

fn save_json_entries(path: &str, entries: &[JournalEntry]) -> Result<(), String> {
    if let Some(parent) = Path::new(path).parent() {
        let _ = fs::create_dir_all(parent);
    }
    let json = serde_json::to_string(entries).map_err(|e| format!("Failed to serialize json: {}", e))?;
    fs::write(path, json).map_err(|e| format!("Failed to write json: {}", e))
}

fn load_sqlite_entries(db_path: &str) -> Result<Vec<JournalEntry>, String> {
    ensure_sqlite_schema(db_path)?;
    let db = sqlite_ffi::open_db(db_path)?;
    use std::ffi::CString;
    let sql = "SELECT id, title, date, content, priority FROM entries ORDER BY id;";
    let c_sql = CString::new(sql).unwrap();
    let mut stmt: *mut std::ffi::c_void = std::ptr::null_mut();
    let rc = unsafe { sqlite_ffi::sqlite3_prepare_v2(db, c_sql.as_ptr(), -1, &mut stmt, std::ptr::null_mut()) };
    if rc != sqlite_ffi::SQLITE_OK {
        sqlite_ffi::close(db);
        return Err(format!("Failed to prepare stmt"));
    }
    let mut entries = Vec::new();
    loop {
        let rc_step = unsafe { sqlite_ffi::sqlite3_step(stmt) };
        if rc_step == sqlite_ffi::SQLITE_ROW {
            let id = unsafe { sqlite_ffi::sqlite3_column_int(stmt, 0) } as u32;
            let title_ptr = unsafe { sqlite_ffi::sqlite3_column_text(stmt, 1) };
            let date_ptr = unsafe { sqlite_ffi::sqlite3_column_text(stmt, 2) };
            let content_ptr = unsafe { sqlite_ffi::sqlite3_column_text(stmt, 3) };
            let priority_type = unsafe { sqlite_ffi::sqlite3_column_type(stmt, 4) };
            let priority = if priority_type == sqlite_ffi::SQLITE_NULL {
                None
            } else {
                Some(unsafe { sqlite_ffi::sqlite3_column_int(stmt, 4) } as u32)
            };
            let cstr_to_string = |ptr: *const u8| -> String {
                if ptr.is_null() {
                    "".to_string()
                } else {
                    unsafe {
                        let c_str = std::ffi::CStr::from_ptr(ptr as *const i8);
                        c_str.to_string_lossy().to_string()
                    }
                }
            };
            let title = cstr_to_string(title_ptr);
            let date = cstr_to_string(date_ptr);
            let content = cstr_to_string(content_ptr);
            let tags = load_sqlite_tags_for_entry(db, id).unwrap_or_default();
            entries.push(JournalEntry { id, date, title, content, tags, priority });
        } else if rc_step == sqlite_ffi::SQLITE_DONE {
            break;
        } else {
            break;
        }
    }
    unsafe { sqlite_ffi::sqlite3_finalize(stmt); }
    sqlite_ffi::close(db);
    Ok(entries)
}

fn load_sqlite_tags_for_entry(db: *mut std::ffi::c_void, entry_id: u32) -> Result<Vec<String>, String> {
    use std::ffi::CString;
    let sql = format!("SELECT tag FROM tags WHERE entry_id = {};", entry_id);
    let c_sql = CString::new(sql).unwrap();
    let mut stmt: *mut std::ffi::c_void = std::ptr::null_mut();
    let rc = unsafe { sqlite_ffi::sqlite3_prepare_v2(db, c_sql.as_ptr(), -1, &mut stmt, std::ptr::null_mut()) };
    if rc != sqlite_ffi::SQLITE_OK {
        return Ok(vec![]);
    }
    let mut tags = Vec::new();
    loop {
        let rc_step = unsafe { sqlite_ffi::sqlite3_step(stmt) };
        if rc_step == sqlite_ffi::SQLITE_ROW {
            let tag_ptr = unsafe { sqlite_ffi::sqlite3_column_text(stmt, 0) };
            let tag = if tag_ptr.is_null() { "".to_string() } else {
                unsafe {
                    let c_str = std::ffi::CStr::from_ptr(tag_ptr as *const i8);
                    c_str.to_string_lossy().to_string()
                }
            };
            tags.push(tag);
        } else {
            break;
        }
    }
    unsafe { sqlite_ffi::sqlite3_finalize(stmt); }
    Ok(tags)
}

fn save_sqlite_entries(db_path: &str, entries: &[JournalEntry]) -> Result<(), String> {
    ensure_sqlite_schema(db_path)?;
    let db = sqlite_ffi::open_db(db_path)?;
    sqlite_ffi::exec(db, "DELETE FROM tags;").map_err(|e| e)?;
    sqlite_ffi::exec(db, "DELETE FROM entries;").map_err(|e| e)?;
    for e in entries {
        let esc = |s: &str| s.replace('\'', "''");
        let title = esc(&e.title);
        let date = esc(&e.date);
        let content = esc(&e.content);
        let priority_sql = if let Some(p) = e.priority { p.to_string() } else { "NULL".to_string() };
        let sql = format!("INSERT INTO entries (id, title, date, content, priority) VALUES ({}, '{}', '{}', '{}', {});", e.id, title, date, content, priority_sql);
        sqlite_ffi::exec(db, &sql).map_err(|e| e)?;
        for tag in &e.tags {
            let tag_esc = esc(tag);
            let sql_tag = format!("INSERT INTO tags (entry_id, tag) VALUES ({}, '{}');", e.id, tag_esc);
            let _ = sqlite_ffi::exec(db, &sql_tag);
        }
    }
    sqlite_ffi::close(db);
    Ok(())
}

fn assign_priority_to_entries(entries: &mut [JournalEntry], priority: u32) {
    for e in entries.iter_mut() {
        if e.priority.is_none() {
            e.priority = Some(priority);
        }
    }
}

fn import_transfer_file(path: &str) -> Result<TransferFile, String> {
    let content = fs::read_to_string(path).map_err(|_| format!("Import file doesn't exist: path {}", path))?;
    serde_json::from_str::<TransferFile>(&content).map_err(|e| {
        format!("Error while parsing import file. Error: {}", e)
    })
}

fn run_tui_app(cfg: Config, json_path: String, sqlite_path: String) -> Result<(), String> {
    use crossterm::terminal::{enable_raw_mode, disable_raw_mode, EnterAlternateScreen, LeaveAlternateScreen};
    use crossterm::ExecutableCommand;
    use std::io::stdout;

    if enable_raw_mode().is_err() {
        return Err("No such device or address (os error 6)".to_string());
    }
    let _ = disable_raw_mode();

    let mut entries: Vec<JournalEntry> = match cfg.backend_type {
        BackendType::Json => load_json_entries(&json_path).unwrap_or_default(),
        BackendType::Sqlite => load_sqlite_entries(&sqlite_path).unwrap_or_default(),
    };

    enable_raw_mode().map_err(|_| "No such device or address (os error 6)".to_string())?;
    let mut stdout = stdout();
    stdout.execute(EnterAlternateScreen).map_err(|_| "No such device or address (os error 6)".to_string())?;
    let backend = ratatui::backend::CrosstermBackend::new(stdout);
    let mut terminal = ratatui::Terminal::new(backend).map_err(|_| "No such device or address (os error 6)".to_string())?;

    let mut selected: usize = 0;

    loop {
        terminal.draw(|f| {
            let size = f.area();
            let chunks = ratatui::layout::Layout::default()
                .direction(ratatui::layout::Direction::Horizontal)
                .constraints([ratatui::layout::Constraint::Percentage(35), ratatui::layout::Constraint::Percentage(65)].as_ref())
                .split(size);
            let items: Vec<ratatui::widgets::ListItem> = if entries.is_empty() {
                vec![ratatui::widgets::ListItem::new("Use 'n' to create new entry")]
            } else {
                entries.iter().map(|e| {
                    let priority_str = if let Some(p) = e.priority { format!("Priority: {}", p) } else { "".to_string() };
                    let tags_str = e.tags.join(" | ");
                    let line1 = format!("{}", e.title);
                    let line2 = format!("{} {}", e.date, priority_str);
                    let line3 = tags_str;
                    ratatui::widgets::ListItem::new(format!("{}\n{}\n{}", line1, line2, line3))
                }).collect()
            };
            let list = ratatui::widgets::List::new(items)
                .block(ratatui::widgets::Block::default().borders(ratatui::widgets::Borders::ALL).title("Journals"));
            f.render_widget(list, chunks[0]);
            let content = if entries.is_empty() {
                "".to_string()
            } else {
                entries[selected].content.clone()
            };
            let content_block = ratatui::widgets::Paragraph::new(content)
                .block(ratatui::widgets::Block::default().borders(ratatui::widgets::Borders::ALL).title("Content"));
            f.render_widget(content_block, chunks[1]);
        }).unwrap();

        if crossterm::event::poll(std::time::Duration::from_millis(200)).unwrap() {
            if let crossterm::event::Event::Key(key) = crossterm::event::read().unwrap() {
                match key.code {
                    crossterm::event::KeyCode::Char('q') => break,
                    crossterm::event::KeyCode::Char('j') | crossterm::event::KeyCode::Down => {
                        if !entries.is_empty() && selected + 1 < entries.len() { selected += 1; }
                    },
                    crossterm::event::KeyCode::Char('k') | crossterm::event::KeyCode::Up => {
                        if selected > 0 { selected -= 1; }
                    },
                    _ => {}
                }
            }
        }
    }

    disable_raw_mode().unwrap();
    terminal.backend_mut().execute(LeaveAlternateScreen).unwrap();
    terminal.show_cursor().unwrap();

    match cfg.backend_type {
        BackendType::Json => { let _ = save_json_entries(&json_path, &entries); },
        BackendType::Sqlite => { let _ = save_sqlite_entries(&sqlite_path, &entries); }
    }

    Ok(())
}

fn main() {
    let matches = Command::new("tjournal")
        .version("0.16.1")
        .about("Tui app allows writing and managing journals/notes from within the terminal With different local back-ends")
        .arg(Arg::new("json-file-path")
            .short('j')
            .long("json-file-path")
            .value_name("FILE PATH")
            .help("Sets the entries Json file path and starts using it")
            .action(ArgAction::Set)
        )
        .arg(Arg::new("sqlite-file-path")
            .short('s')
            .long("sqlite-file-path")
            .value_name("FILE PATH")
            .help("Sets the entries sqlite file path and starts using it")
            .action(ArgAction::Set)
        )
        .arg(Arg::new("backend-type")
            .short('b')
            .long("backend-type")
            .value_name("BACKEND_TYPE")
            .help("Sets the backend type and starts using it")
            .value_parser(["json", "sqlite"])
            .action(ArgAction::Set)
        )
        .arg(Arg::new("config")
            .short('c')
            .long("config")
            .value_name("DIR PATH")
            .help("Specifies the path for the configuration directory.\nConfiguration files is considered as root for themes file too.\nIt still accepts the path for configuration file for backward compatibility.\n(default path: /home/agent/.config/tui-journal)")
            .action(ArgAction::Set)
        )
        .arg(Arg::new("verbose")
            .short('v')
            .long("verbose")
            .help("Increases logging verbosity each use for up to 3 times")
            .action(ArgAction::Count)
        )
        .arg(Arg::new("log")
            .short('l')
            .long("log")
            .value_name("FILE PATH")
            .help("Specifies a file to use for logging\n(default file: /home/agent/.cache/tui-journal/tui-journal.log)")
            .action(ArgAction::Set)
        )
        .subcommand(Command::new("print-config")
            .about("Print the current settings including the paths for the back-end files")
            .alias("pc")
        )
        .subcommand(Command::new("import-journals")
            .about("Import journals from the given transfer JSON file to the current back-end file")
            .alias("imj")
            .arg(Arg::new("path")
                .short('p')
                .long("path")
                .value_name("FILE PATH")
                .help("Path of the JSON file to import from")
                .required(true)
                .action(ArgAction::Set)
            )
        )
        .subcommand(Command::new("assign-priority")
            .about("Assign priority for all the entries with empty priority field")
            .alias("ap")
            .arg(Arg::new("PRIORITY")
                .value_name("PRIORITY")
                .help("Priority value (Positive number)")
                .required(true)
                .value_parser(value_parser!(u32))
                .action(ArgAction::Set)
            )
        )
        .subcommand(Command::new("theme")
            .about("Provides commands regarding changing themes and styles of the app")
            .alias("style")
            .subcommand(Command::new("print-path")
                .about("Prints the path to the user themes file")
                .alias("path")
            )
            .subcommand(Command::new("print-default")
                .about("Dumps the styles with the default values to be used as a reference and base for user custom themes")
                .alias("default")
            )
            .subcommand(Command::new("write-defaults")
                .about("Creates user custom themes file if doesn't exist then writes the default styles to it")
                .alias("write")
            )
        )
        .get_matches();

    let verbose = *matches.get_one::<u8>("verbose").unwrap_or(&0);
    let log_path_opt = matches.get_one::<String>("log").cloned();

    let mut log_file_handle: Option<std::fs::File> = None;
    match init_logging(log_path_opt.as_ref(), verbose) {
        Ok(f) => { log_file_handle = f; },
        Err(e) => {
            eprintln!("Error: {}", e);
            std::process::exit(1);
        }
    }

    if verbose > 0 {
        log_trace_init(&mut log_file_handle);
    }

    let config_custom = matches.get_one::<String>("config").cloned();
    let config_paths = match resolve_config_path(config_custom.as_ref()) {
        Ok(p) => p,
        Err(e) => {
            eprintln!("Error: {}", e);
            std::process::exit(1);
        }
    };

    let mut config = match load_config(&config_paths) {
        Ok(c) => c,
        Err(e) => {
            eprintln!("Error: {}", e);
            std::process::exit(1);
        }
    };

    if let Some(j_path) = matches.get_one::<String>("json-file-path") {
        config.json_backend.file_path = j_path.clone();
    }
    if let Some(s_path) = matches.get_one::<String>("sqlite-file-path") {
        config.sqlite_backend.file_path = s_path.clone();
    }
    if let Some(bt_str) = matches.get_one::<String>("backend-type") {
        match bt_str.as_str() {
            "json" => config.backend_type = BackendType::Json,
            "sqlite" => config.backend_type = BackendType::Sqlite,
            _ => {}
        }
    }

    if let Some((sub_name, sub_matches)) = matches.subcommand() {
        match sub_name {
            "print-config" => {
                handle_print_config(config);
                return;
            },
            "import-journals" => {
                let import_path = sub_matches.get_one::<String>("path").unwrap().clone();
                let transfer = match import_transfer_file(&import_path) {
                    Ok(tf) => tf,
                    Err(err_msg) => {
                        use crossterm::terminal::{enable_raw_mode, disable_raw_mode};
                        if enable_raw_mode().is_err() {
                            eprintln!("Error: No such device or address (os error 6)");
                            std::process::exit(1);
                        }
                        let _ = disable_raw_mode();
                        use crossterm::terminal::{EnterAlternateScreen, LeaveAlternateScreen};
                        use crossterm::ExecutableCommand;
                        use std::io::stdout;
                        let _ = enable_raw_mode();
                        let mut stdout = stdout();
                        let _ = stdout.execute(EnterAlternateScreen);
                        let backend = ratatui::backend::CrosstermBackend::new(stdout);
                        let mut terminal = ratatui::Terminal::new(backend).unwrap();
                        let mut first = true;
                        loop {
                            terminal.draw(|f| {
                                let area = f.area();
                                let block = ratatui::widgets::Block::default().borders(ratatui::widgets::Borders::ALL).title("Journals");
                                f.render_widget(block, area);
                                let popup_area = ratatui::layout::Rect { x: area.width/4, y: area.height/3, width: area.width/2, height: 7 };
                                let paragraph = ratatui::widgets::Paragraph::new(err_msg.clone())
                                    .block(ratatui::widgets::Block::default().borders(ratatui::widgets::Borders::ALL).title("Error"));
                                f.render_widget(ratatui::widgets::Clear, popup_area);
                                f.render_widget(paragraph, popup_area);
                            }).unwrap();
                            if !first {
                                if crossterm::event::poll(std::time::Duration::from_millis(200)).unwrap() {
                                    if let crossterm::event::Event::Key(k) = crossterm::event::read().unwrap() {
                                        let _ = k;
                                        break;
                                    }
                                }
                            } else {
                                std::thread::sleep(std::time::Duration::from_millis(200));
                                first = false;
                            }
                        }
                        if let Ok(_) = disable_raw_mode() {
                            terminal.backend_mut().execute(LeaveAlternateScreen).unwrap();
                            terminal.show_cursor().unwrap();
                        }
                        return;
                    }
                };
                let json_path = config.json_backend.file_path.clone();
                let sqlite_path = config.sqlite_backend.file_path.clone();
                match config.backend_type {
                    BackendType::Json => {
                        let mut entries = load_json_entries(&json_path).unwrap_or_default();
                        let mut next_id = if entries.is_empty() { 0 } else { entries.iter().map(|e| e.id).max().unwrap_or(0) + 1 };
                        for te in transfer.entries {
                            let je = JournalEntry {
                                id: next_id,
                                date: te.date,
                                title: te.title,
                                content: te.content,
                                tags: te.tags,
                                priority: te.priority,
                            };
                            next_id += 1;
                            entries.push(je);
                        }
                        let _ = save_json_entries(&json_path, &entries);
                    },
                    BackendType::Sqlite => {
                        let mut entries = load_sqlite_entries(&sqlite_path).unwrap_or_default();
                        let mut next_id = if entries.is_empty() { 1 } else { entries.iter().map(|e| e.id).max().unwrap_or(0) + 1 };
                        for te in transfer.entries {
                            let je = JournalEntry {
                                id: next_id,
                                date: te.date,
                                title: te.title,
                                content: te.content,
                                tags: te.tags,
                                priority: te.priority,
                            };
                            next_id += 1;
                            entries.push(je);
                        }
                        let _ = save_sqlite_entries(&sqlite_path, &entries);
                    }
                }
                let res = run_tui_app(config, json_path, sqlite_path);
                if let Err(e) = res {
                    eprintln!("Error: {}", e);
                    std::process::exit(1);
                }
                return;
            },
            "assign-priority" => {
                let prio = *sub_matches.get_one::<u32>("PRIORITY").unwrap();
                let json_path = config.json_backend.file_path.clone();
                let sqlite_path = config.sqlite_backend.file_path.clone();
                match config.backend_type {
                    BackendType::Json => {
                        let mut entries = load_json_entries(&json_path).unwrap_or_default();
                        assign_priority_to_entries(&mut entries, prio);
                        let _ = save_json_entries(&json_path, &entries);
                    },
                    BackendType::Sqlite => {
                        let mut entries = load_sqlite_entries(&sqlite_path).unwrap_or_default();
                        assign_priority_to_entries(&mut entries, prio);
                        let _ = save_sqlite_entries(&sqlite_path, &entries);
                    }
                }
                let res = run_tui_app(config, json_path, sqlite_path);
                if let Err(e) = res {
                    eprintln!("Error: {}", e);
                    std::process::exit(1);
                }
                return;
            },
            "theme" => {
                if let Some((theme_sub, _)) = sub_matches.subcommand() {
                    match theme_sub {
                        "print-path" => {
                            match get_themes_path(&config_paths, &mut log_file_handle) {
                                Ok(p) => {
                                    println!("{}", p.display());
                                },
                                Err(e) => {
                                    eprintln!("Error: {}", e);
                                    std::process::exit(1);
                                }
                            }
                            return;
                        },
                        "print-default" => {
                            print!("{}", themes_default_content());
                            return;
                        },
                        "write-defaults" => {
                            match get_themes_path(&config_paths, &mut log_file_handle) {
                                Ok(p) => {
                                    if p.exists() {
                                        eprintln!("Error: Themes file already exists. Path: {}", p.display());
                                        std::process::exit(1);
                                    }
                                    if let Some(parent) = p.parent() {
                                        if let Err(e) = fs::create_dir_all(parent) {
                                            eprintln!("Error: Error while writing default themes to file\n\nCaused by:\n    {}", e);
                                            std::process::exit(1);
                                        }
                                    }
                                    match fs::write(&p, themes_default_content()) {
                                        Ok(_) => {
                                            println!("Default themes have been written to {}", p.display());
                                        },
                                        Err(e) => {
                                            eprintln!("Error: Error while writing default themes to file\n\nCaused by:\n    {}", e);
                                            std::process::exit(1);
                                        }
                                    }
                                },
                                Err(e) => {
                                    eprintln!("Error: {}", e);
                                    std::process::exit(1);
                                }
                            }
                            return;
                        },
                        _ => {}
                    }
                }
                println!("Provides commands regarding changing themes and styles of the app");
                return;
            },
            _ => {}
        }
    }

    let json_path = config.json_backend.file_path.clone();
    let sqlite_path = config.sqlite_backend.file_path.clone();
    match run_tui_app(config, json_path, sqlite_path) {
        Ok(_) => {},
        Err(e) => {
            eprintln!("Error: {}", e);
            std::process::exit(1);
        }
    }
}
