use clap::{Arg, ArgAction, Command, value_parser};
use std::path::{Path, PathBuf};
use std::fs;
use std::io::Write;

#[derive(Debug, Clone)]
enum BackendType {
    Json,
    Sqlite,
}

impl std::fmt::Display for BackendType {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            BackendType::Json => write!(f, "Json"),
            BackendType::Sqlite => write!(f, "Sqlite"),
        }
    }
}

impl<'de> serde::Deserialize<'de> for BackendType {
    fn deserialize<D>(deserializer: D) -> Result<Self, D::Error>
    where D: serde::Deserializer<'de> {
        let s = String::deserialize(deserializer)?;
        match s.to_ascii_lowercase().as_str() {
            "json" => Ok(BackendType::Json),
            "sqlite" => Ok(BackendType::Sqlite),
            _ => Err(serde::de::Error::unknown_variant(&s, &["Json", "Sqlite"])),
        }
    }
}

impl serde::Serialize for BackendType {
    fn serialize<S>(&self, serializer: S) -> Result<S::Ok, S::Error>
    where S: serde::Serializer {
        serializer.serialize_str(&self.to_string())
    }
}

#[derive(Debug, Clone, serde::Deserialize, serde::Serialize)]
#[serde(rename_all = "snake_case")]
enum DatumVisibility {
    #[serde(rename = "show")]
    Show,
    #[serde(rename = "hide")]
    Hide,
    #[serde(rename = "empty_line")]
    EmptyLine,
}

impl std::fmt::Display for DatumVisibility {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            DatumVisibility::Show => write!(f, "show"),
            DatumVisibility::Hide => write!(f, "hide"),
            DatumVisibility::EmptyLine => write!(f, "empty_line"),
        }
    }
}

#[derive(Debug, Default, Clone, serde::Deserialize, serde::Serialize)]
struct ExportConfig {
    #[serde(default = "default_true")]
    show_confirmation: bool,
    #[serde(skip_serializing_if = "Option::is_none")]
    default_path: Option<String>,
}

fn default_true() -> bool { true }

#[derive(Debug, Default, Clone, serde::Deserialize, serde::Serialize)]
struct ExternalEditorConfig {
    #[serde(skip_serializing_if = "Option::is_none")]
    command: Option<String>,
    #[serde(default)]
    args: Vec<String>,
    #[serde(default)]
    auto_save: bool,
    #[serde(default = "default_txt")]
    temp_file_extension: String,
