        // default, don't check existence
        let home = dirs::home_dir().unwrap_or_else(|| PathBuf::from("/home/agent"));
        Ok(home.join(".config/tui-journal/themes.toml"))
    }
}

mod sqlite_ffi {
    use std::ffi::{CString, CStr};
    use std::os::raw::{c_char, c_int};

    #[link(name = "sqlite3")]
    extern "C" {
        pub fn sqlite3_open(filename: *const c_char, ppDb: *mut *mut std::ffi::c_void) -> c_int;
        pub fn sqlite3_close(db: *mut std::ffi::c_void) -> c_int;
        pub fn sqlite3_exec(db: *mut std::ffi::c_void, sql: *const c_char, callback: Option<extern "C" fn(*mut std::ffi::c_void, c_int, *mut *mut c_char, *mut *mut c_char) -> c_int>, arg: *mut std::ffi::c_void, errmsg: *mut *mut c_char) -> c_int;
        pub fn sqlite3_free(ptr: *mut std::ffi::c_void);
        pub fn sqlite3_prepare_v2(db: *mut std::ffi::c_void, zSql: *const c_char, nByte: c_int, ppStmt: *mut *mut std::ffi::c_void, pzTail: *mut *const c_char) -> c_int;
        pub fn sqlite3_step(stmt: *mut std::ffi::c_void) -> c_int;
        pub fn sqlite3_finalize(stmt: *mut std::ffi::c_void) -> c_int;
        pub fn sqlite3_column_int(stmt: *mut std::ffi::c_void, iCol: c_int) -> c_int;
        pub fn sqlite3_column_text(stmt: *mut std::ffi::c_void, iCol: c_int) -> *const u8;
        pub fn sqlite3_column_type(stmt: *mut std::ffi::c_void, iCol: c_int) -> c_int;
    }

    pub const SQLITE_OK: i32 = 0;
    pub const SQLITE_ROW: i32 = 100;
    pub const SQLITE_DONE: i32 = 101;
    pub const SQLITE_NULL: i32 = 5;

    pub fn open_db(path: &str) -> Result<*mut std::ffi::c_void, String> {
        let c_path = CString::new(path).unwrap();
        let mut db: *mut std::ffi::c_void = std::ptr::null_mut();
        let rc = unsafe { sqlite3_open(c_path.as_ptr(), &mut db) };
        if rc != SQLITE_OK { Err(format!("Failed to open db: {}", path)) } else { Ok(db) }
    }

    pub fn exec(db: *mut std::ffi::c_void, sql: &str) -> Result<(), String> {
        let c_sql = CString::new(sql).unwrap();
        let mut errmsg: *mut c_char = std::ptr::null_mut();
        let rc = unsafe { sqlite3_exec(db, c_sql.as_ptr(), None, std::ptr::null_mut(), &mut errmsg) };
        if rc != SQLITE_OK {
            let msg = if !errmsg.is_null() {
                let c_str = unsafe { CStr::from_ptr(errmsg) };
                let s = c_str.to_string_lossy().to_string();
                unsafe { sqlite3_free(errmsg as *mut std::ffi::c_void) };
                s
            } else { format!("sqlite error code {}", rc) };
            Err(msg)
        } else { Ok(()) }
    }

    pub fn close(db: *mut std::ffi::c_void) { unsafe { sqlite3_close(db); } }
}

fn ensure_sqlite_schema(db_path: &str) -> Result<(), String> {
    let db = sqlite_ffi::open_db(db_path)?;
    let sql_entries = r#"
    CREATE TABLE IF NOT EXISTS entries (
        id INTEGER PRIMARY KEY NOT NULL,
        title TEXT NOT NULL,
        date DATE NOT NULL,
        content TEXT,
        priority INTEGER DEFAULT NULL
    );
    "#;
    let sql_tags = r#"
    CREATE TABLE IF NOT EXISTS tags (
        entry_id INTEGER NOT NULL,
        tag TEXT NOT NULL,
        PRIMARY KEY (entry_id, tag)
        FOREIGN KEY (entry_id) REFERENCES entries (id) ON DELETE CASCADE
    );
    "#;
    let sql_migrations = r#"
    CREATE TABLE IF NOT EXISTS _sqlx_migrations (
        version BIGINT PRIMARY KEY,
        description TEXT NOT NULL,
        installed_on TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
        success BOOLEAN NOT NULL,
        checksum BLOB NOT NULL,
        execution_time BIGINT NOT NULL
    );
    "#;
    sqlite_ffi::exec(db, sql_migrations).map_err(|e| e)?;
    sqlite_ffi::exec(db, sql_entries).map_err(|e| e)?;
    sqlite_ffi::exec(db, sql_tags).map_err(|e| e)?;
    sqlite_ffi::close(db);
    Ok(())
}

fn load_json_entries(path: &str) -> Result<Vec<JournalEntry>, String> {
    if !Path::new(path).exists() {
        if let Some(parent) = Path::new(path).parent() { let _ = fs::create_dir_all(parent); }
        let _ = fs::write(path, "[]");
        return Ok(vec![]);
    }
    let content = fs::read_to_string(path).map_err(|e| format!("Failed to read json file: {}", e))?;
    if content.trim().is_empty() { return Ok(vec![]); }
    serde_json::from_str(&content).map_err(|e| format!("Failed to parse json: {}", e))
}

fn save_json_entries(path: &str, entries: &[JournalEntry]) -> Result<(), String> {
    if let Some(parent) = Path::new(path).parent() { let _ = fs::create_dir_all(parent); }
    let json = serde_json::to_string(entries).map_err(|e| format!("Failed to serialize json: {}", e))?;
    fs::write(path, json).map_err(|e| format!("Failed to write json: {}", e))
}

fn load_sqlite_entries(db_path: &str) -> Result<Vec<JournalEntry>, String> {
    ensure_sqlite_schema(db_path)?;
    let db = sqlite_ffi::open_db(db_path)?;
    use std::ffi::CString;
    let sql = "SELECT id, title, date, content, priority FROM entries ORDER BY id;";
    let c_sql = CString::new(sql).unwrap();
    let mut stmt: *mut std::ffi::c_void = std::ptr::null_mut();
    let rc = unsafe { sqlite_ffi::sqlite3_prepare_v2(db, c_sql.as_ptr(), -1, &mut stmt, std::ptr::null_mut()) };
    if rc != sqlite_ffi::SQLITE_OK { sqlite_ffi::close(db); return Err("Failed to prepare stmt".to_string()); }
    let mut entries = Vec::new();
    loop {
        let rc_step = unsafe { sqlite_ffi::sqlite3_step(stmt) };
        if rc_step == sqlite_ffi::SQLITE_ROW {
            let id = unsafe { sqlite_ffi::sqlite3_column_int(stmt, 0) } as u32;
            let title_ptr = unsafe { sqlite_ffi::sqlite3_column_text(stmt, 1) };
            let date_ptr = unsafe { sqlite_ffi::sqlite3_column_text(stmt, 2) };
            let content_ptr = unsafe { sqlite_ffi::sqlite3_column_text(stmt, 3) };
            let priority_type = unsafe { sqlite_ffi::sqlite3_column_type(stmt, 4) };
            let priority = if priority_type == sqlite_ffi::SQLITE_NULL { None } else { Some(unsafe { sqlite_ffi::sqlite3_column_int(stmt, 4) } as u32) };
            let cstr_to_string = |ptr: *const u8| -> String {
                if ptr.is_null() { "".to_string() } else { unsafe { let c_str = std::ffi::CStr::from_ptr(ptr as *const i8); c_str.to_string_lossy().to_string() } }
            };
            let title = cstr_to_string(title_ptr);
            let date = cstr_to_string(date_ptr);
            let content = cstr_to_string(content_ptr);
            let tags = load_sqlite_tags_for_entry(db, id).unwrap_or_default();
            entries.push(JournalEntry { id, date, title, content, tags, priority });
        } else if rc_step == sqlite_ffi::SQLITE_DONE { break; } else { break; }
    }
    unsafe { sqlite_ffi::sqlite3_finalize(stmt); }
    sqlite_ffi::close(db);
    Ok(entries)
}

fn load_sqlite_tags_for_entry(db: *mut std::ffi::c_void, entry_id: u32) -> Result<Vec<String>, String> {
    use std::ffi::CString;
    let sql = format!("SELECT tag FROM tags WHERE entry_id = {};", entry_id);
    let c_sql = CString::new(sql).unwrap();
    let mut stmt: *mut std::ffi::c_void = std::ptr::null_mut();
    let rc = unsafe { sqlite_ffi::sqlite3_prepare_v2(db, c_sql.as_ptr(), -1, &mut stmt, std::ptr::null_mut()) };
    if rc != sqlite_ffi::SQLITE_OK { return Ok(vec![]); }
    let mut tags = Vec::new();
    loop {
        let rc_step = unsafe { sqlite_ffi::sqlite3_step(stmt) };
        if rc_step == sqlite_ffi::SQLITE_ROW {
            let tag_ptr = unsafe { sqlite_ffi::sqlite3_column_text(stmt, 0) };
            let tag = if tag_ptr.is_null() { "".to_string() } else { unsafe { let c_str = std::ffi::CStr::from_ptr(tag_ptr as *const i8); c_str.to_string_lossy().to_string() } };
            tags.push(tag);
        } else { break; }
    }
    unsafe { sqlite_ffi::sqlite3_finalize(stmt); }
    Ok(tags)
}

fn save_sqlite_entries(db_path: &str, entries: &[JournalEntry]) -> Result<(), String> {
    ensure_sqlite_schema(db_path)?;
    let db = sqlite_ffi::open_db(db_path)?;
    sqlite_ffi::exec(db, "DELETE FROM tags;").map_err(|e| e)?;
    sqlite_ffi::exec(db, "DELETE FROM entries;").map_err(|e| e)?;
    for e in entries {
        let esc = |s: &str| s.replace('\'', "''");
        let title = esc(&e.title);
        let date = esc(&e.date);
        let content = esc(&e.content);
        let priority_sql = if let Some(p) = e.priority { p.to_string() } else { "NULL".to_string() };
        let sql = format!("INSERT INTO entries (id, title, date, content, priority) VALUES ({}, '{}', '{}', '{}', {});", e.id, title, date, content, priority_sql);
        sqlite_ffi::exec(db, &sql).map_err(|e| e)?;
        for tag in &e.tags {
            let tag_esc = esc(tag);
            let sql_tag = format!("INSERT INTO tags (entry_id, tag) VALUES ({}, '{}');", e.id, tag_esc);
            let _ = sqlite_ffi::exec(db, &sql_tag);
        }
    }
    sqlite_ffi::close(db);
    Ok(())
}

fn assign_priority_to_entries(entries: &mut [JournalEntry], priority: u32) {
    for e in entries.iter_mut() { if e.priority.is_none() { e.priority = Some(priority); } }
}

